export class GameEngine {
  private lastTime = performance.now();
  private animFrameId: number | null = null;
  private isRunning = false;

  start(): void {
    this.isRunning = true;
    this.lastTime = performance.now();
    this.loop(this.lastTime);
  }

  private loop = (time: number): void => {
    if (!this.isRunning) return;
    const dt = Math.min(0.1, (time - this.lastTime) / 1000);
    this.lastTime = time;

    this.update(dt);
    this.render();

    this.animFrameId = requestAnimationFrame(this.loop);
  };

  update(dt: number): void {
    // Physics & entity update logic
  }

  render(): void {
    // Canvas drawing logic
  }

  stop(): void {
    this.isRunning = false;
    if (this.animFrameId) cancelAnimationFrame(this.animFrameId);
  }
}

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export function checkAABB(a: Rect, b: Rect): boolean {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

export function drawSpriteFrame(
  ctx: CanvasRenderingContext2D,
  image: CanvasImageSource,
  frameIndex: number,
  frameWidth: number,
  frameHeight: number,
  destX: number,
  destY: number,
  cols: number
): void {
  const sx = (frameIndex % cols) * frameWidth;
  const sy = Math.floor(frameIndex / cols) * frameHeight;
  ctx.drawImage(image, sx, sy, frameWidth, frameHeight, destX, destY, frameWidth, frameHeight);
}
